from pathlib import Path
import json,re
B=Path(__file__).resolve().parent
names=json.loads((B/'projects.json').read_text(encoding='utf-8'))
# Domain-specific practice is intentionally distinct from the shared scaffold guarantees.
domains={
35:('an equipment checkout and its custodian','Camera kit for field interviews','Return date','Add a checkout/return history view','Retain separate checkout and return timestamps; do not infer both from a generic updated timestamp.','Prevent checking out an already checked-out asset','Model the borrower and permitted transitions explicitly and validate the current locked asset before changing it.'),
36:('a maintenance work order and its responsible technician','Inspect west-wing ventilation','Maintenance due date','Show overdue open work orders','Compare calendar dates and exclude Completed; keep an unset due date separate from overdue.','Add recurring maintenance','Create a separate recurrence rule and generate uniquely identified occurrences; repeating a status command must not generate extra work orders.'),
37:('a library loan and its responsible borrower','Loan a reference atlas','Return due date','Display days overdue for unreturned loans','Use an explicit as-of date in tests and exclude Returned records; do not label a missing due date as late.','Track copies of the same book','Give each copy its own id and availability; a title is not a unique physical item identifier.'),
38:('a gym membership and its account owner','Beginner strength membership','Review or renewal date','Show paused memberships separately','Derive the view from status and keep its filter consistent with counts and paging.','Add a pause interval','Store start/end calendar dates, validate ordering and define whether pausing changes billing; the current status alone cannot answer that.'),
39:('a marketing campaign and its coordinator','Autumn email welcome campaign','Campaign deadline','Add a budget-versus-actual view','Store actual spend separately from the existing amount field and derive the difference; an edit to budget should not rewrite spend.','Schedule campaign activation','Separate scheduled time from current status and make the activation job repeat-safe with an explicit occurrence key.'),
40:('a volunteer shift and its coordinator','Saturday food-bank shift','Shift deadline','Show unfilled upcoming shifts','Filter Open records by an explicit date window; Draft and Complete mean different workflow states.','Add volunteer capacity','Model assignments and unique volunteer/shift pairs; check capacity at the same boundary that commits an assignment.'),
41:('a learning plan and its mentor','Backend fundamentals with weekly review','Learning milestone date','Show completed learning milestones','Add milestone records with evidence and completion dates rather than treating the plan status as proof of every skill.','Require evidence before completion','Define the evidence contract, check it in the same transaction as the status change and explain the rejected transition in the UI.'),
42:('a project risk and its mitigation owner','Supplier delay affects launch','Mitigation review date','Create a probability-impact score','Define bounded independent scales and derive the score; do not reuse the generic amount field without changing its meaning explicitly.','Record formal risk acceptance','Add an acceptance decision record with actor and rationale; the Accepted label currently does not enforce approval authority.'),
43:('a travel request and its requester','Training visit to the regional office','Travel decision deadline','Show requests awaiting a decision','Use Submitted as the explicit filter and preserve the same filter in count and rows.','Separate approval from booking','Define which actors and states can approve or book, enforce server-side rules and record the decision atomically; current status names alone do not authorize anything.'),
44:('a vendor contract and its responsible owner','Annual monitoring software agreement','Renewal deadline','Build a renewal-window view','Use calendar dates and include Active/Renewal as defined by the product rule; expired and undated contracts need separate handling.','Track contract versions','Keep immutable version records and a current-version pointer; editing a generic notes field is not a version history.'),
45:('a procurement request and its requester','Developer workstation purchase','Decision deadline','Group pending requests by category','Aggregate the same filtered records as the list and state whether totals cover all matches or only the current page.','Add approval thresholds','Define currency, amount bounds and authorized approvers; a UI-hidden Approved option alone cannot enforce the rule.'),
46:('a rental unit and its responsible property owner','One-bedroom courtyard unit','Follow-up date','Distinguish available from maintenance units','Use the actual statuses and show why Maintenance is not an available vacancy even when there is no occupant.','Prevent overlapping tenancies','Create tenancy interval records with explicit endpoint semantics and enforce non-overlap when committing; generic unit status is insufficient.'),
47:('a quality audit and its responsible reviewer','Quarterly access-control audit','Remediation deadline','Show audits needing remediation','Filter Needs Remediation and derive overdue state using calendar labels; Passed is not overdue remediation.','Model findings and evidence','Add child findings with severity and resolution evidence; decide which unresolved findings block Passed and validate within the status transaction.'),
48:('a fictional intake record and its coordinator','Demo intake for a fictional learner','Follow-up date','Show reviewing intakes awaiting follow-up','Use synthetic fixtures and the Reviewing status; derive the date view without inventing clinical urgency from generic priority.','Design restricted record access','Introduce a real authentication/authorization boundary and test denied reads and writes. This scaffold currently has no role-based access or clinical workflow policy.'),
49:('a grant application and its owner','Community learning grant proposal','Submission or review deadline','Show submissions awaiting review','Use Submitted/Under Review according to an explicit view rule; keep draft amounts distinct from awards.','Separate requested and awarded amounts','Add two named amounts and a decision record; Awarded status alone must not silently reinterpret an existing request amount.'),
50:('an operational incident and its commander','Intermittent checkout latency','Response follow-up deadline','Build an incident status timeline','Display ordered transition events and distinguish notes from actual status changes; duplicate commands must not inflate the timeline.','Track mitigation and resolution durations','Store explicit occurrence timestamps and define reopening semantics. Do not derive all milestones from one mutable updated timestamp.')
}
out=[]
for sql,file in [(True,'domain-specs.json'),(False,'memory-domain-specs.json')]:
 for d in json.loads((B/file).read_text(encoding='utf-8')):
  n=int(d['stage']);root=B/'stage'/str(n);domain,title,date_label,ex1,ans1,ex4,ans4=domains[n]
  s0,s1=d['statuses'][:2];route=d['route'];cat=d['categories'][0]
  source='server/src/index.ts' if sql else next(p.relative_to(root).as_posix() for p in root.glob('server/**/*.js') if 'setStatus(' in p.read_text(encoding='utf-8') and 'setStatus(id' in p.read_text(encoding='utf-8'))
  symbol=f'app.patch("{route}/:id/status"' if sql else 'setStatus'
  before='Status requests could add redundant history. Validation accepted malformed shapes, and page calculations lacked a consistent clamped result.'
  if sql:before+=' Separate status and history writes could disagree after a late failure; separate count/page queries could see different snapshots. Seed dueDate values also needed correct JSON-to-SQL field mapping.'
  after='Typed and bounded inputs protect edits, real calendar dates round-trip, page numbers clamp and equal sort values use an id tie-breaker. Repeating the current status creates no extra status history.'
  if sql:after+=' Status and audit writes use one row-locked transaction; count and rows share a repeatable-read snapshot. Seed dates map to the intended column.'
  else:after+=' Actual changes update the in-memory record and append one status event.'
  model=f'This app represents {domain}. A record uses generic fields id, title, owner, category, status, priority, amount, dueDate and notes. Categories are {", ".join(d["categories"])}. Statuses are {", ".join(d["statuses"])}. The UI gives these shared fields domain-specific labels. {date_label} is represented as a YYYY-MM-DD calendar string, not an instant.'
  model+=(' PostgreSQL items and activity_entries tables persist records and their child history.' if sql else ' A repository array and its activity collection live only in the Node process. Restarting the server restores seeds; this change does not add durable storage.')
  concept=f'Follow one concrete command: change "{title}" from {s0} to {s1}. The first successful command represents a real transition and adds one status event. Sending {s1} again compares equal to current state, so it returns the record without adding another status event. Created, updated and note entries remain separate kinds; counting every timeline row would give the wrong assertion. This guarantee concerns repeated current values, not global request deduplication. After an intervening transition, requesting {s1} can legitimately create a new event.\n\n'
  concept+=('The handler obtains one database client, begins a transaction and reads the record FOR UPDATE. A second writer waits for that row, then compares against its latest committed status. The update and activity insert use the same client, so an audit-insert failure rolls back the status too. The test installs a temporary trigger to force that late failure. Separately, the list transaction counts and fetches under one repeatable-read snapshot. It does not freeze the dataset across later HTTP requests. PostgreSQL DATE values are returned as calendar strings through a type parser, avoiding accidental local-midnight conversion.\n\n' if sql else 'The repository owns the live array. Its status method checks existence, compares the current value, then changes the record and appends history synchronously. There is no await between those operations. This makes the repeat-safe behavior easy to trace inside one Node process, but it is not a durable database transaction or a multi-process coordination strategy. A server restart discards new records and history. The API tests use a fresh process fixture and real HTTP, so they check routing and validation as well as repository behavior.\n\n')
  concept+=f'Validation belongs at the API boundary even when the React controls constrain input. An object is not a valid title, an unknown priority is not silently accepted, and 2027-02-29 is not a real date. Normalization may trim a valid string, but should not stringify an object into a misleading title. For paging, count matching rows before clamping a request such as page 999. Sort by the selected field and then id so ties are deterministic on an unchanged dataset. The scaffold accepts its named statuses; it does not enforce a domain approval graph or actor permissions. A {s0}-to-{s1} label change alone does not implement every real-world rule for {domain}.'
  exercises=[ex1,f'Add a UI confirmation for changing {s1} back to {s0}.',f'Add a regression for a {date_label.lower()} at a leap-year boundary.',ex4]
  answers=[ans1,'Cancellation must preserve state and history. Confirmation calls the existing status endpoint; keep server validation and repeat-safe handling because API callers can bypass the dialog.','Use 2028-02-29 as valid and 2027-02-29 as invalid. Assert the valid string survives a read and the rejected edit leaves the old record unchanged; do not test only error wording.',ans4]
  test=next(root.glob('test/*.test.ts' if sql else 'test/*.test.js'))
  out.append(dict(stage=n,title=names[n-21].split('/')[-1].replace('-',' ').title()+': reliable workflow and history',focus='atomic status transitions, consistent pages and calendar dates' if sql else 'repeat-safe workflow history and explicit input contracts',before=before,after=after,model=model,concept=concept,example=f'Create "{title}" in {cat} with status {s0}, amount 12.50 and dueDate 2028-02-29. Request {s1} twice: one status event is added. An edit with dueDate 2027-02-29 returns 400 and preserves the old record. With three matching records and pageSize 2, page 999 clamps to page 2 with one item.'+(' A forced activity-insert failure leaves both the record and its prior history unchanged.' if sql else ''),exercises=exercises,answers=answers,source=source,symbol=symbol,test=test.relative_to(root).as_posix(),domain=d,fixture_title=title,sql=sql))
(B/'course-specific-3.json').write_text(json.dumps(out,indent=2),encoding='utf-8')
print('Wrote sixteen domain course specifications')
